\label{thm:critical-set-finite}
For every $s\in(0,1/2]$ there exists $p_0\in(0,1/2)$ such that $\overline H_s$ is strictly
increasing on $(0,p_0]$. In particular, the critical set $D_s$ is finite.

\label{thm:minkowski-reconstruction}
Let $\{S_i\}_{i=1}^N$ be a self-similar IFS on $[0,1]$ satisfying the open set condition,
with contraction ratios $r_i$ and attractor $K$. Assume that its
similarity dimension $s$ lies in $(0,1)$, and let $\mu$ be the self-similar probability measure
with weights $r_i^s$. Then
\begin{equation}\label{eq:minkowski-reconstruction}
  \nu_{W(K),e^{-n}}\to W_*\mu
  \quad\text{weakly almost surely as }n\to\infty.
\end{equation}
In particular, $W_*\mu$ is almost surely a Borel function of the compact set $W(K)$.

\label{thm:gaussian-reduction}
For every $r>0$,
\begin{equation}\label{eq:gaussian-reduction}
  \begin{split}
    \mathbb{E}\mathcal{C}_r(W_*\mu)
    &=\int_{[0,1]^2}\left(1-\exp\left(-\frac{r^2}{2\abs{u-t}}\right)\right)
      \,\mathrm{d}\mu(u)\,\mathrm{d}\mu(t)\\
    &=\int_0^1\left(1-\exp\left(-\frac{r^2}{2\delta}\right)\right)
      \,\mathrm{d}\mathcal{C}_\delta(\mu).
  \end{split}
\end{equation}

\label{thm:cross-piece-mass}
There exist $C>0$ and $\eta\in(0,1-s)$ such that
\begin{equation}\label{eq:cross-piece-mass}
  0\leqslant\mathcal{C}^\times_\delta(\mu)\leqslant C\delta^{s+\eta},\qquad0<\delta\leqslant1.
\end{equation}
Consequently, $0\leqslant z(t)\leqslant Ce^{-\eta t}$ for all $t\geqslant0$.

\label{thm:smoothing-injective}
The operator $T$ is injective on the continuous $\ell$-periodic functions. Further,
$Tg$ can be constant only when $g$ is constant.

\label{thm:neighbourhood-moments}
For every $q\geqslant1$, there is $C_q>0$ such that, for $0<r\leqslant1$,
\begin{equation}\label{eq:neighbourhood-moment-bound}
  \mathbb{E}\bigl[\mathcal{L}^2(\langle E\rangle_r)^q\bigr]
  +\mathbb{E}\bigl[M_r(E)^q\bigr]
  \leqslant C_qr^{q(2-2s)}.
\end{equation}
There is also $c>0$ such that, for $0<r\leqslant1$,
\begin{equation}\label{eq:neighbourhood-mean-lower-bound}
  \mathbb{E} M_r(E)\geqslant cr^{2-2s}.
\end{equation}

\label{thm:neighbourhood-overlap}
There exists $C>0$ such that, for all distinct $i,j\in\{1,\ldots,N\}$ and all $0<r\leqslant1$,
\[
  \mathbb{E}\mathcal{L}^2(\langleW(S_i(K))\rangle_r\cap\langleW(S_j(K))\rangle_r)
  \leqslant Cr^{2-2s+2\eta}.
\]
Moreover,
\begin{equation}\label{eq:neighbourhood-defect-mean}
  \mathbb{E} D_r\leqslant Cr^{2-2s+2\eta}.
\end{equation}

\label{thm:neighbourhood-renewal}
There exist constants $0<c\leqslant C<\infty$ such that $c\leqslant Q(t)\leqslant C$ for every $t\geqslant0$.
Moreover, for every $i$,
\begin{equation}\label{eq:neighbourhood-renewal-shift}
  Q(t-\alpha_i/2)-Q(t)\to0
  \qquad\text{as }t\to\infty.
\end{equation}

\label{thm:neighbourhood-concentration}
There exist constants $C,\gamma>0$ such that, for every $t\geqslant0$,
\[
  \operatorname{Var}\bigl(e^{(2-2s)t}M_{e^{-t}}(E)\bigr)\leqslant Ce^{-\gamma t}.
\]
Consequently, for every fixed $\tau\in\mathbb{R}$, we have
\begin{equation}\label{eq:neighbourhood-grid-concentration}
  e^{(2-2s)(n+\tau)}M_{e^{-(n+\tau)}}(E)-Q(n+\tau)\to0
  \qquad\text{almost surely as }n\to\infty.
\end{equation}

\label{thm:base-five-profiles}
For every integer $n\geqslant1$,
\begin{equation}\label{eq:base-five-correlation}
  \mathcal{C}_{5^{-n}}(\mu_1)=\frac32\,3^{-n}-\frac12\,9^{-n},
  \qquad \mathcal{C}_{5^{-n}}(\mu_2)=3^{-n}.
\end{equation}
In particular, the expected Brownian correlation profiles satisfy
\[
  \limsup_{t\to\infty}\abs{H_{\mu_1}^s(t)-H_{\mu_2}^s(t)}>0.
\]

\label{thm:fixed-dimension-profiles}
For every $p\in(0,1)$ and $r>0$,
\begin{equation}\label{eq:fixed-dimension-correlation}
    \mathbb{E}\mathcal{C}_r(W_*\mu_p)
    =\sum_{j,k\geqslant0}\binom{j+k}{j}p^{2j}q^{2k}
    \cdot\int_0^1\left(1-\exp\left(-\frac{r^2}{2\lambda_1^j\lambda_2^k\delta}\right)\right)
      \,\mathrm{d}\mathcal{C}^\times_\delta(\mu_p).
\end{equation}
The mean profile exists and satisfies
\begin{equation}\label{eq:fixed-dimension-mean}
  \overline H_s(p)=\frac{2^{-s}\Gamma(1-s)}{h(p)}
    \int_0^1\delta^{-s}\,\mathrm{d}\mathcal{C}^\times_\delta(\mu_p).
\end{equation}
If $\log\lambda_1/\log\lambda_2\notin\mathbb{Q}$, then $H_{\mu_p}^s(t)\to\overline H_s(p)$ as
$t\to\infty$.

\label{thm:level-sums}
Let $U\subset\mathbb{C}$ be an open disc on which $\lambda_1$ and $\lambda_2$ are holomorphic and
bounded in modulus by some $\rho<1$, with $\rho B^2<1$. Let $D\subset\mathbb{C}$ be a bounded open convex set
containing $x_w(z)$ for every $z\in U$ and every finite word $w$, and let $\psi$ be holomorphic
on $U\times D\times D$ with $\abs{\partial_x\psi},\abs{\partial_y\psi}\leqslant L$.
Then the level sums converge uniformly on $U$ to a holomorphic function $\Lambda$ with
\begin{equation}\label{eq:level-sum-bound}
  \sup_{z\in U}\abs{\Lambda(z)-\psi(z;0,0)}\leqslant\frac{4LB^2}{1-\rho B^2},
\end{equation}
and $\Lambda(p)=\mathbb{E}\,\psi(p;X,Y)$ for every $p\in U\cap(0,1)$.

\label{thm:second-derivative-small-s}
Let $0<s\leqslant2\cdot10^{-5}$ and $10^{-4}\leqslant p\leqslant1/2$. Then
$\abs{J''(p)}\leqslant10^{11}s\gamma$.
